window.GENERA=[{"name":"Agaricus","de":"Egerlinge, Champignons","dgfm":true,"merke":"Freie Lamellen, jung rosa bis graurosa, reif schokoladenbraun; Ring; schokoladenbraunes Sporenpulver; keine Scheide.","mk":"Hut fleischig, weiß, ocker oder braun, glatt bis faserig-schuppig. Lamellen frei, dicht, jung rosa bis graurosa (bei Wald- und Anisegerlingen auch grauweißlich), mit der Sporenreife schokoladenbraun bis schwarzbraun. Stiel mit einfachem, doppeltem oder zahnradartigem Ring; Stielbasis teils knollig verdickt, aber nie in einer häutigen Scheide. Fleisch je nach Art unveränderlich, gilbend oder rötend; der Geruch (Anis, Bittermandel, Karbol/Tinte, Mandel) ist ein wichtiges Bestimmungsmerkmal.","sp":"Schokoladen- bis purpurbraun.","oeko":"Saprobionten auf Wiesen, Weiden, in Wäldern, Parks und Gärten, meist auf nährstoffreichem Boden.","speise":"Viele gute Speisepilze (Wiesen-, Schaf-, Anis-, Riesen-, Wald-Champignon u. a., DGfM-Positivliste). Anis-Egerlinge reichern Cadmium an – nur gelegentlich essen.","gift":"Karbol-Egerling (A. xanthodermus) und Verwandte (Gruppe Xanthodermatei): Magen-Darm-Syndrom. Erkennbar am Karbol-/Tintengeruch und an der beim Anschneiden der Stielbasis sofort chromgelb verfärbenden Rinde.","abgr":"Knollenblätterpilze (Amanita): Lamellen bleiben weiß, Sporenpulver weiß, Volva oder Knolle – lebensgefährliche Verwechslung besonders bei jungen Egerlingen. Riesenschirmlinge: Sporenpulver weiß. Träuschlinge: Lamellen angewachsen, Sporenpulver purpurbraun.","arten":"Wiesen-Champignon (A. campestris), Schaf-Egerling (A. arvensis), Riesen-Egerling (A. augustus), Wald-Egerling (A. silvaticus), Karbol-Egerling (A. xanthodermus, giftig)","tipp":"Bei Prüfung und Beratung immer die Stielbasis ankratzen (Gilbung, Geruch) und auf rosa bis braune, freie Lamellen sowie das braune Sporenpulver achten.","id":"agaricus","incl":[],"fam":"Agaricaceae"},{"name":"Agrocybe","de":"Ackerlinge","dgfm":true,"merke":"Ocker- bis lederfarbene Hüte, tabakbraune Lamellen und Sporen, oft mit häutigem Ring.","mk":"Kleine bis mittelgroße Lamellenpilze mit glattem, oft rissigem, creme- bis ockerbraunem Hut. Lamellen angewachsen, erst blass, dann ton- bis tabakbraun. Stiel faserig, bei manchen Arten mit häutigem Ring (Frühlings-Ackerling). Mikroskopisch zellige Huthaut und Sporen mit Keimporus.","sp":"Tabak- bis dunkelbraun.","oeko":"Saprobionten auf Wiesen, in Gärten, auf Rindenmulch und Holzhäcksel; der Südliche Ackerling (Cyclocybe cylindracea) wächst büschelig an Pappeln und Weiden.","speise":"Frühlings-Ackerling uneinheitlich beurteilt (gelegentlich Magen-Darm-Beschwerden); Südlicher Ackerling (Cyclocybe cylindracea) essbar (DGfM-Positivliste).","abgr":"Träuschlinge: Sporenpulver dunkel purpurbraun. Risspilze: Hut faserig-rissig, spermatischer Geruch, giftig. Fälblinge: Rettichgeruch, Sporenpulver tonbraun, giftig. Samthäubchen: zierlicher, rostbraune Sporen.","arten":"Frühlings-Ackerling (A. praecox), Südlicher Ackerling (Cyclocybe cylindracea)","tipp":"Frühjahrspilz mit Ring und tabakbraunem Sporenpulver – nicht mit weißsporigen Mairitterlingen verwechseln.","id":"agrocybe","incl":[],"fam":"Strophariaceae"},{"name":"Albatrellus","de":"Schafporlinge, Bodenporlinge","dgfm":true,"merke":"Fleischige, am Boden wachsende, zentral gestielte Porlinge mit feinen, herablaufenden Poren – alle Arten besonders geschützt (§§).","mk":"Hut fleischig, oft unregelmäßig, mit zentralem bis exzentrischem Stiel; Poren fein, weiß bis gelblich, am Stiel herablaufend; Fleisch weich bis brüchig, nicht holzig. Mehrere Fruchtkörper oft verwachsen.","sp":"Weiß.","oeko":"Mykorrhizapilze, vor allem bei Nadelbäumen (Fichte, Tanne), meist auf Kalk oder in Bergwäldern.","speise":"Schafporling, Semmelporling und Ziegenfuß-Porling sind essbar (DGfM-Positivliste), dürfen aber nicht gesammelt werden.","abgr":"Stielporlinge (Polyporus): an Holz, zäh-ledrig. Semmel-Stoppelpilz: Stacheln statt Poren. Klapperschwamm: viele Hütchen an Eiche.","arten":"Schafporling (A. ovinus), Semmelporling (A. confluens), Ziegenfuß-Porling (A. pes-caprae), Kamm-Porling (A. cristatus)","tipp":"BArtSchV: alle heimischen Albatrellus-Arten sind besonders geschützt (§§) – Sammelverbot.","id":"albatrellus","incl":[],"fam":"Albatrellaceae"},{"name":"Amanita","de":"Knollenblätterpilze, Wulstlinge, Scheidenstreiflinge","dgfm":true,"merke":"Freie, weiße Lamellen, weißes Sporenpulver und eine Gesamthülle: Volva bzw. Knolle an der Stielbasis, oft Hüllreste auf dem Hut, meist ein Ring.","mk":"Fruchtkörper entstehen aus einem geschlossenen „Ei“ (Gesamthülle, Velum universale). Diese bleibt als häutige Scheide (Volva), als gerandete oder gegürtelte Knolle und/oder als Flocken und Hautfetzen auf dem Hut zurück. Die Teilhülle (Velum partiale) bildet einen Ring (fehlt bei den Scheidenstreiflingen). Lamellen frei, weiß (selten gelblich); Hut leicht vom Stiel lösbar; Hutrand bei Scheidenstreiflingen und Fliegenpilzen gerieft.","sp":"Weiß.","oeko":"Mykorrhizapilze in Laub- und Nadelwäldern, Parks und Heiden.","speise":"Perlpilz (A. rubescens), Grauer Wulstling (A. excelsa) und Scheidenstreiflinge sind essbar, aber roh giftig (nur gut gegart); Kaiserling (§§).","gift":"Grüner, Weißer (Frühlings-) und Spitzhütiger Knollenblätterpilz: Amatoxine – Phalloides-Syndrom, tödlich. Fliegenpilz, Pantherpilz, Königs-Fliegenpilz: Pantherina-Syndrom. Gelber Knollenblätterpilz: roh meiden. Fransen-Wulstling u. a.: nierenschädigendes Proxima-Syndrom.","abgr":"Champignons: Lamellen rosa, dann braun. Täublinge: ohne Volva und Ring, kreidig-brüchiges Fleisch. Scheidlinge (Volvariella): Volva, aber rosa Lamellen und rosa Sporen. Riesenschirmlinge: verschiebbarer Ring, ohne Volva.","arten":"Grüner Knollenblätterpilz (A. phalloides), Spitzhütiger Knollenblätterpilz (A. virosa), Fliegenpilz (A. muscaria), Pantherpilz (A. pantherina), Perlpilz (A. rubescens), Grauer Scheidenstreifling (A. vaginata)","tipp":"Pilze immer vollständig mit Stielbasis ausdrehen – Volva und Knolle bleiben sonst im Boden! Beim Grünen Knollenblätterpilz genügen etwa 50 g für eine tödliche Vergiftung.","id":"amanita","incl":[],"fam":"Amanitaceae"},{"name":"Armillaria","de":"Hallimasche","dgfm":true,"merke":"Büschelig an Holz, Hut mit dunklen Schüppchen, weißes Sporenpulver, meist mit Ring, schwarze Myzelstränge (Rhizomorphen).","mk":"Hut honiggelb bis braun, zur Mitte mit dunklen Haarschüppchen; Lamellen weißlich bis cremefarben, angewachsen bis kurz herablaufend, alt fleckig; Stiel faserig, mit häutigem oder wattig-spinnwebigem Ring (beim Ringlosen Hallimasch fehlend), Basis oft verdickt oder bei büscheligen Arten spitz zulaufend. Unter der Rinde und im Boden schwarze, schnürsenkelartige Rhizomorphen.","sp":"Weiß bis blass creme.","oeko":"Parasiten und Saprobionten an lebenden und toten Laub- und Nadelbäumen; verursachen Weißfäule und können ganze Bestände schädigen.","speise":"Uneinheitlich beurteilt (DGfM): individuelle Magen-Darm-Beschwerden; roh giftig, nur gut durchgegart (mindestens 20 Minuten).","abgr":"Gift-Häubling (Galerina marginata): Sporenpulver rostbraun, kleiner – tödlich giftig. Stockschwämmchen und Schüpplinge: Sporenpulver rostbraun. Schwefelköpfe: Sporenpulver violettbraun, ohne Hutschuppen.","arten":"Honiggelber Hallimasch (A. mellea), Dunkler Hallimasch (A. ostoyae), Gelbschuppiger Hallimasch (A. lutea), Ringloser Hallimasch (Desarmillaria tabescens)","tipp":"Die heimischen Arten unterscheiden sich durch Ausbildung des Rings (häutig, wattig-dick oder spinnwebig), Hutfarbe und Beschuppung, Form der Stielbasis, Wuchsweise (büschelig oder einzeln) und Substrat (Laub- oder Nadelholz).","id":"armillaria","incl":[],"fam":"Physalacriaceae"},{"name":"Auricularia","de":"Ohrlappenpilze","dgfm":true,"merke":"Gallertig-elastische, ohrförmige Fruchtkörper an Holz, die eintrocknen und bei Regen wieder aufquellen.","mk":"Fruchtkörper ohr-, muschel- bis schüsselförmig, gummiartig-gallertig; Oberseite fein samtig-filzig, Unterseite (Fruchtschicht) glatt bis aderig gefaltet; trocken hart und geschrumpft, feucht wieder elastisch.","sp":"Weiß.","oeko":"Saprobionten und Schwächeparasiten an Laubholz; das Judasohr vor allem an Holunder, der Gezonte Ohrlappenpilz an Ulme, Pappel und anderen Laubhölzern.","speise":"Judasohr (A. auricula-judae) und A. cornea s. l. (Mu-Err) essbar (DGfM-Positivliste). Der Gezonte Ohrlappenpilz ist zäh und kein Speisepilz.","abgr":"Becherlinge: wachsartig-brüchig, nicht gallertig. Drüslinge (Exidia): schwarz, warzig, hirnartig. Zitterlinge (Tremella): gelb, hirnartig gelappt.","arten":"Judasohr (A. auricula-judae), Gezonter Ohrlappenpilz (A. mesenterica)","tipp":"Judasohr = ohrförmig, braun, an Holunder – ganzjährig zu finden.","id":"auricularia","incl":[],"fam":"Auriculariaceae"},{"name":"Bolbitius","de":"Mistpilze","dgfm":true,"merke":"Zarte, kurzlebige Pilze mit schleimigem, gerieftem Hut und rostbraunem Sporenpulver auf Dung und gedüngten Wiesen.","mk":"Hut sehr dünn, schleimig-schmierig, Rand gerieft, beim Goldmistpilz jung leuchtend eigelb, rasch ausblassend; Lamellen frei bis angeheftet, gelblich, dann rost- bis zimtbraun; Stiel hohl, zerbrechlich, bereift. Fruchtkörper vergehen oft schon nach einem Tag.","sp":"Rostbraun.","oeko":"Saprobionten auf Dung, Stroh, Kompost und gedüngten Wiesen.","speise":"Keine Speisepilze.","abgr":"Samthäubchen (Conocybe): Hut nicht schleimig. Saftlinge: wachsartige Lamellen, weißes Sporenpulver. Düngerlinge: schwarzes Sporenpulver, gescheckte Lamellen.","arten":"Goldmistpilz (B. titubans)","tipp":"Eigelber, schleimiger, zerbrechlicher Hut auf Mist = Goldmistpilz.","id":"bolbitius","incl":[],"fam":"Bolbitiaceae"},{"name":"Boletus","de":"Dickröhrlinge","dgfm":true,"incl":["Butyriboletus","Caloboletus","Cyanoboletus","Hemileccinum","Neoboletus","Rubroboletus","Suillellus"],"merke":"Fleischige Röhrlinge mit dickem, oft bauchigem, genetztem oder beflocktem Stiel und leicht vom Hut lösbarer Röhrenschicht.","mk":"Hut fleischig, trocken bis schwach schmierig; Röhrenschicht leicht vom Hutfleisch ablösbar; Poren je nach Art weiß, gelb oder rot; Stiel dick, oft bauchig bis knollig, mit Netz (Steinpilze, Butterröhrlinge, Netzstieliger Hexenröhrling) oder mit Flöckchen (Flockenstieliger Hexenröhrling); Fleisch fest, unveränderlich oder blauend.","sp":"Olivbraun.","oeko":"Mykorrhizapilze bei Laub- und Nadelbäumen.","speise":"Steinpilze (Boletus s. str.), Hexenröhrlinge (roh giftig, nur gut gegart) und Butterröhrlinge sind gute Speisepilze. Fichten-Steinpilz: geschützt (§, nur geringe Mengen für den Eigenbedarf); Bronze-Röhrling, Königs-Röhrling, Fechtners Butterröhrling und Anhängsel-Röhrling: §§ (Sammelverbot).","gift":"Satanspilz: Magen-Darm-Syndrom. Schönfuß- und Wurzelnder Bitterröhrling: bitter, magen-darm-giftig. Schwarzblauender Röhrling: reichert Arsen an.","abgr":"Gallen-Röhrling (Tylopilus): Poren rosa, dunkles Netz, gallebitter. Filzröhrlinge: kleiner, schlanker Stiel ohne Netz, weite Poren. Raufußröhrlinge: Stiel mit Schüppchen.","arten":"Fichten-Steinpilz (B. edulis), Sommer-Steinpilz (B. reticulatus), Flockenstieliger Hexenröhrling (Neoboletus erythropus), Netzstieliger Hexenröhrling (Suillellus luridus), Satanspilz (Rubroboletus satanas), Schönfuß-Röhrling (Caloboletus calopus)","tipp":"Wichtige Gattungsmerkmale: dicker, fleischiger Stiel; Stiel oft genetzt; Röhren leicht ablösbar; festes Fleisch; olivbraunes Sporenpulver; Mykorrhiza. Rote Poren sind kein Giftigkeitsmerkmal (Hexenröhrlinge sind essbar).","id":"boletus","fam":"Boletaceae"},{"name":"Clitopilus","de":"Mehlräslinge","dgfm":true,"merke":"Weißgrauer, wildlederartiger Hut, herablaufende, später rosa Lamellen, rosa Sporenpulver und starker Mehlgeruch.","mk":"Hut weiß bis grauweiß, matt, wie Wildleder, oft unregelmäßig verbogen; Lamellen weit herablaufend, dicht, erst weißlich, dann fleischrosa; Stiel kurz, oft exzentrisch; Fleisch weiß, weich; Geruch kräftig mehl- bis gurkenartig.","sp":"Rosa.","oeko":"Saprobiont oder fakultativer Mykorrhizapartner in Laub- und Nadelwäldern, oft in der Nähe von Steinpilzen.","speise":"Mehl-Räsling (C. prunulus) essbar (DGfM-Positivliste).","abgr":"Weiße Trichterlinge (Feld-Trichterling, Bleiweißer Trichterling): Sporenpulver weiß, enthalten Muscarin – lebensgefährlich! Rötlinge: Lamellen nicht herablaufend.","arten":"Mehl-Räsling (C. prunulus)","tipp":"Nur mit Sporenpulverprobe (rosa) sicher von den giftigen weißen Trichterlingen zu trennen.","id":"clitopilus","incl":[],"fam":"Entolomataceae"},{"name":"Conocybe","de":"Samthäubchen","dgfm":true,"fam":"Bolbitiaceae","merke":"Kleine, zerbrechliche Pilze mit glockigem, ocker- bis rostbraunem Hut, langem dünnem Stiel und rostbraunem Sporenpulver.","mk":"Hut kegelig bis glockig, ocker- bis rostbraun, oft hygrophan; Lamellen angeheftet, rostbraun; Stiel lang, dünn, sehr zerbrechlich, oft fein bereift; einige verwandte Arten (Pholiotina) mit Ring.","sp":"Rostbraun.","oeko":"Saprobionten in Wiesen, Rasen, an Wegrändern, auf Dung und Holzresten.","speise":"Keine Speisepilze.","gift":"Der Runzlige Glockenschüppling (Conocybe filaris, Syn. Pholiotina rugosa) ist amatoxinverdächtig – bisher nur ein Fallbericht aus Nordamerika, in deutschem Material kein Amanitin nachgewiesen (DGfM); Pholiotina cyanopus enthält Psilocybin.","abgr":"Mistpilze (Bolbitius): Hut schleimig. Häublinge (Galerina): an Moos und Holz, teils tödlich giftig. Kahlköpfe: Sporenpulver purpurbraun.","arten":"Milchweißes Samthäubchen (C. apala)","tipp":"Kleine Braunsporer sind für die Speisepilzberatung tabu.","id":"conocybe","incl":[]},{"name":"Coprinus","de":"Tintlinge","dgfm":true,"incl":["Coprinellus","Coprinopsis","Parasola"],"merke":"Lamellen sehr dicht, zerfließen bei der Reife zu schwarzer „Tinte“; Sporenpulver schwarz.","mk":"Hut dünn, walzen-, ei- oder glockenförmig, oft mit Velumresten (Schuppen, Flocken, glitzernde Körnchen); Lamellen frei bis angeheftet, sehr dicht, erst weiß, dann rosa bis schwarz und bei den meisten Arten von unten her zerfließend (Autolyse); Fruchtkörper kurzlebig. Rädchentintlinge (Parasola) zerfließen nicht, sondern welken.","sp":"Schwarz.","oeko":"Saprobionten auf nährstoffreichem Boden, Rasen, Holz, Dung und Schutt.","speise":"Schopf-Tintling (Coprinus comatus) jung essbar (DGfM-Positivliste), nur mit weißen Lamellen.","gift":"Falten-Tintling (Coprinopsis atramentaria) und in geringem Maß der Glimmer-Tintling enthalten Coprin: Acetaldehyd-(Coprinus-)Syndrom bei Alkoholgenuss bis etwa 3 Tage nach der Mahlzeit.","abgr":"Mürblinge (Psathyrella): Lamellen zerfließen nicht. Düngerlinge: gescheckte Lamellen, nicht zerfließend.","arten":"Schopf-Tintling (C. comatus), Falten-Tintling (Coprinopsis atramentaria), Glimmer-Tintling (Coprinellus micaceus), Gesäter Tintling (Coprinellus disseminatus), Rädchentintling (Parasola plicatilis)","tipp":"Der Schopf-Tintling enthält kein Coprin; der Falten-Tintling schon – Alkoholverbot!","id":"coprinus","fam":"Agaricaceae"},{"name":"Cortinarius","de":"Schleierlinge","dgfm":true,"merke":"Spinnwebartiger Schleier (Cortina) zwischen Hutrand und Stiel und rostbraunes Sporenpulver.","mk":"Junge Fruchtkörper mit Cortina, deren Reste später als rostbraun bestäubte Fasern am Stiel hängen; Lamellen jung oft lebhaft gefärbt (violett, gelb, orange, olivbraun), reif rostbraun; mit Abstand die artenreichste Lamellenpilz-Gattung. Untergattungen: Schleimköpfe (Phlegmacium, Hut schleimig, Stiel trocken, oft gerandete Knolle), Schleimfüße (Myxacium, Hut und Stiel schleimig), Gürtelfüße (Telamonia, hygrophan, Velumgürtel am Stiel), Hautköpfe (Dermocybe, trocken, lebhaft gelb, orange oder rot), Rauköpfe (Leprocybe, trocken, filzig-schuppig), Seidenköpfe (Sericeocybe).","sp":"Rostbraun.","oeko":"Mykorrhizapilze bei Laub- und Nadelbäumen.","speise":"Wenige Speisepilze, z. B. Reifpilz (C. caperatus), Schleiereule (C. praestans), Blauer Schleimfuß (C. collinitus) (DGfM-Positivliste). Wegen der Verwechslungsgefahr nur für Erfahrene.","gift":"Orangefuchsiger und Spitzgebuckelter Raukopf (C. orellanus, C. rubellus): Orellanus-Syndrom mit Nierenversagen nach 2–20 Tagen Latenz – tödlich. Grün, gelb, orange oder rot gefärbte Arten gelten als verdächtig.","abgr":"Fälblinge (Hebeloma): tonbraune Sporen, Rettichgeruch, Lamellen oft mit Tröpfchen. Risspilze (Inocybe): Hut radialfaserig-rissig. Rötelritterlinge: Sporenpulver blass rosa, keine Cortina.","arten":"Reifpilz (C. caperatus), Schleiereule (C. praestans), Orangefuchsiger Raukopf (C. orellanus), Spitzgebuckelter Raukopf (C. rubellus), Blutroter Hautkopf (C. sanguineus)","tipp":"Zwei Gattungsmerkmale: Cortina und rostbraunes Sporenpulver. Untergattungen kennen (Phlegmacium, Myxacium, Telamonia, Dermocybe, Leprocybe).","id":"cortinarius","incl":[],"fam":"Cortinariaceae"},{"name":"Cystoderma","de":"Körnchenschirmlinge","dgfm":true,"merke":"Hut und Stiel unterhalb des Rings mit körnig-mehligem Velum; weißes Sporenpulver.","mk":"Kleine bis mittelgroße Pilze; Hut ocker, orange bis rot, mit körnigem, mehligem Belag; Lamellen weiß bis creme, angewachsen; Stiel unterhalb eines meist vergänglichen, körnigen Rings mit gleichfarbigen Körnchen, darüber glatt.","sp":"Weiß.","oeko":"Saprobionten in Moos und Nadelstreu, oft auf sauren Böden.","speise":"Keine Speisepilze.","abgr":"Mehlschirmlinge (Cystolepiota): Lamellen frei, Velum weiß mehlig, ohne Ring. Schirmlinge (Lepiota): Lamellen frei, Hut beschuppt.","arten":"Amiant-Körnchenschirmling (C. amianthinum), Starkriechender Körnchenschirmling (C. carcharias)","tipp":"Körniger Hut und „gestiefelter“ Stiel (Körnchen bis zum Ring).","id":"cystoderma","incl":[],"fam":"Squamanitaceae"},{"name":"Cystolepiota","de":"Mehlschirmlinge","dgfm":true,"merke":"Kleine Schirmlinge, die wie mit Mehl bestäubt aussehen; Lamellen frei, Sporenpulver weiß.","mk":"Hut und Stiel mit weißem bis rosa, mehlig-flockigem, abwischbarem Velum; ohne häutigen Ring; Lamellen frei, weiß; Fruchtkörper klein und zart.","sp":"Weiß.","oeko":"Saprobionten in der Laubstreu, oft auf Kalk.","speise":"Keine Speisepilze.","abgr":"Körnchenschirmlinge: Lamellen angewachsen, körniges Velum. Schirmlinge (Lepiota): Hut mit Schüppchen auf hellem Grund, oft giftig.","arten":"Weißer Mehlschirmling (C. seminuda)","tipp":"Mehlig bepuderter Winzling mit freien Lamellen.","id":"cystolepiota","incl":[],"fam":"Agaricaceae"},{"name":"Entoloma","de":"Rötlinge","dgfm":true,"merke":"Rosa Sporenpulver, angewachsene bis ausgebuchtete (nicht freie) Lamellen, die jung weißlich oder grau und reif rosa sind; kein Velum.","mk":"Lamellen angewachsen bis ausgebuchtet, jung weiß, grau oder gelblich, durch die Sporen später rosa; kein Ring, keine Volva; Hut oft hygrophan, glatt bis faserig; Geruch häufig mehlartig oder ranzig. Mikroskopisch eckige Sporen (5–8-eckig).","sp":"Rosa (fleischrosa).","oeko":"Saprobionten in Wiesen und Wäldern oder Mykorrhizapartner (Schild-Rötling bei Rosengewächsen).","speise":"Schild-Rötling (E. clypeatum) und Schlehen-Rötling (E. sepium) essbar (DGfM-Positivliste).","gift":"Riesen-Rötling (E. sinuatum) und Frühlings-Rötling (E. vernum): Magen-Darm-Syndrom, beim Riesen-Rötling schwer.","abgr":"Dachpilze (Pluteus): Lamellen frei, an Holz. Scheidlinge: Volva, freie Lamellen. Ritterlinge und Nebelkappe: Sporenpulver weiß. Mehl-Räsling: Lamellen herablaufend.","arten":"Riesen-Rötling (E. sinuatum), Schild-Rötling (E. clypeatum), Frühlings-Rötling (E. vernum)","tipp":"Drei Gattungsmerkmale: rosa Sporenpulver; Lamellen nicht frei, im Alter rosa; eckige Sporen (Mikroskop); kein Velum.","id":"entoloma","incl":[],"fam":"Entolomataceae"},{"name":"Flammulina","de":"Samtfußrüblinge","dgfm":true,"merke":"Büschelig an Laubholz im Winter: orangegelber, schmieriger Hut und samtig schwarzbrauner Stielfuß; weißes Sporenpulver.","mk":"Hut honig- bis orangegelb, schmierig-glänzend; Lamellen weißlich bis blassgelb, ziemlich entfernt; Stiel zäh, oben gelblich, nach unten dunkelbraun bis schwarz und dicht samtig.","sp":"Weiß.","oeko":"Saprobionten und Schwächeparasiten an Laubholz, vor allem Weide und Pappel; fruktifiziert bei Frost (November bis März).","speise":"Gemeiner Samtfußrübling (F. velutipes s. l.) essbar (DGfM-Positivliste); die Zuchtform heißt Enoki.","abgr":"Gift-Häubling: Sporenpulver rostbraun, Stiel mit Ring – tödlich giftig. Schwefelköpfe: Sporenpulver violettbraun. Stockschwämmchen: Ring, schuppiger Stiel, rostbraune Sporen.","arten":"Gemeiner Samtfußrübling (F. velutipes)","tipp":"Winterpilz mit samtigem, schwarzbraunem Stiel – Sporenpulverprobe gegen Gift-Häubling!","id":"flammulina","incl":[],"fam":"Physalacriaceae"},{"name":"Fomitopsis","de":"Baumschwämme","dgfm":true,"incl":["Piptoporus"],"merke":"Harte, mehrjährige oder korkige Konsolenporlinge mit hellem Fleisch und feinen, hellen Poren; verursachen Braunfäule.","mk":"Fruchtkörper konsolen- bis hufförmig, korkig bis holzig; Fleisch hell (weiß bis rosa); Poren fein, weiß bis cremefarben oder rosa. Rotrand-Porling mit rotem bis gelblichem Randwulst und harziger Kruste, die bei Hitze schmilzt; der Birkenporling (heute Fomitopsis betulina) nur an Birke.","sp":"Weiß bis creme.","oeko":"Parasiten und Saprobionten an Nadel- und Laubholz; Braunfäule.","speise":"Keine Speisepilze.","abgr":"Zunderschwamm (Fomes): Fleisch braun und filzig, Weißfäule. Lackporlinge (Ganoderma): braunes Sporenpulver, braunes Fleisch. Feuerschwämme: rostbraunes Fleisch.","arten":"Rotrand-Porling (F. pinicola), Birkenporling (Piptoporus betulinus), Rosenroter Baumschwamm (F. rosea)","tipp":"Rotrand-Porling: Kruste mit Streichholz anschmelzen – Harzgeruch.","id":"fomitopsis","fam":"Fomitopsidaceae"},{"name":"Galerina","de":"Häublinge","dgfm":true,"merke":"Kleine, ocker- bis honigbraune, hygrophane Pilze mit ocker- bis rostbraunem Sporenpulver in Moos oder an Holz – der Gift-Häubling ist tödlich giftig.","mk":"Hut glockig bis gewölbt, ocker- bis honigbraun, hygrophan, oft gerieft; Lamellen angewachsen, ockerbraun; Stiel dünn, mit Ring, Ringzone oder Velumresten (Gift-Häubling: häutiger Ring, darunter silbrig-längsfaserig überfasert).","sp":"Ocker- bis rostbraun.","oeko":"Saprobionten in Moospolstern (oft Torfmoos) und an morschem Holz.","speise":"Keine Speisepilze.","gift":"Gift-Häubling (G. marginata agg.): Amatoxine – Phalloides-Syndrom, tödlich. G. steglichii enthält Psilocybin.","abgr":"Stockschwämmchen (Kuehneromyces mutabilis): Stiel unter dem Ring dunkel sparrig-schuppig, Hut zweifarbig hygrophan, Geruch angenehm. Hallimasch und Samtfußrübling: Sporenpulver weiß. Schwefelköpfe: Sporenpulver violettbraun.","arten":"Gift-Häubling (G. marginata)","tipp":"Büschelig an Holz + rostbraunes Sporenpulver + Ring: immer an den Gift-Häubling denken! Stockschwämmchen nur mit sicherem Merkmal „geschuppter Stiel“ freigeben.","id":"galerina","incl":[],"fam":"Hymenogastraceae"},{"name":"Ganoderma","de":"Lackporlinge","dgfm":true,"merke":"Porlinge mit krustiger, lackglänzender oder matter Oberseite, braunem Fleisch, weißen, auf Druck bräunenden Poren und braunem Sporenpulver.","mk":"Ein- oder mehrjährige Konsolen, beim Glänzenden Lackporling seitlich gestielt und wie lackiert; Flacher Lackporling mit matter, oft kakaobraun mit Sporen bepuderter Kruste; Poren weiß, auf Druck sofort braun („Malerpilz“); Fleisch braun, korkig-faserig.","sp":"Braun (zimt- bis kakaobraun).","oeko":"Parasiten und Saprobionten an Laubholz (Buche, Eiche, Pappel); Weißfäule.","speise":"Keine Speisepilze (holzig); der Glänzende Lackporling wird als „Reishi“ in Asien medizinisch verwendet.","abgr":"Zunderschwamm (Fomes): Poren graubraun, Fleisch filzig, kein Sporenstaub auf der Oberseite. Rotrand-Porling: Poren weiß bis creme, roter Randwulst. Feuerschwämme: Fleisch rostbraun, sehr hart.","arten":"Flacher Lackporling (G. applanatum), Glänzender Lackporling (G. lucidum)","tipp":"In die weiße Unterseite des Flachen Lackporlings lässt sich mit einem Stöckchen bräunlich „zeichnen“.","id":"ganoderma","incl":[],"fam":"Polyporaceae"},{"name":"Gymnopus","de":"Rüblinge","dgfm":true,"incl":["Rhodocollybia","Collybia"],"merke":"Lamellenpilze mit zähem, knorpelig-elastischem Stiel, glattem Hut und weißem bis cremefarbenem Sporenpulver.","mk":"Hut glatt, oft hygrophan; Lamellen frei bis angewachsen, dicht bis entfernt; Stiel zäh-knorpelig, biegsam, oft mit filziger oder wurzelnder Basis; Fleisch dünn. Butter-Rüblinge (Rhodocollybia) mit speckig-glattem Hut und keuligem Stiel, Sklerotien-Rüblinge (Collybia) auf alten Pilzen.","sp":"Weiß bis creme (Rhodocollybia cremerosa).","oeko":"Saprobionten in Laub- und Nadelstreu und an Holz; der Spindelige Rübling als Schwächeparasit an Eiche und Buche.","speise":"Waldfreund-Rübling und Gefleckter Rübling uneinheitlich beurteilt (gelegentlich Magen-Darm-Beschwerden); Knopfstieliger Rübling und Butter-Rübling minderwertig.","gift":"Spindeliger Rübling (G. fusipes): Magen-Darm-Syndrom. Brennender Rübling: brennend scharf.","abgr":"Schwindlinge (Marasmius): sehr zäh, wiederauflebend, oft mit Rosshaarstiel. Helmlinge: Stiel brüchig, Hut gerieft-glockig. Trichterlinge: Lamellen herablaufend.","arten":"Waldfreund-Rübling (G. dryophilus), Brennender Rübling (G. peronatus), Spindeliger Rübling (G. fusipes), Butter-Rübling (Rhodocollybia butyracea), Gefleckter Rübling (Rhodocollybia maculata)","tipp":"Rübling = zäher, knorpeliger Stiel, der sich biegen und verdrehen lässt.","id":"gymnopus","fam":"Omphalotaceae"},{"name":"Gyromitra","de":"Giftlorcheln","dgfm":true,"merke":"Hirnartig gewundener, brauner Hut ohne Waben, innen gekammert – die Frühjahrs-Giftlorchel enthält Gyromitrin und ist tödlich giftig.","mk":"Hut unregelmäßig hirnartig gefaltet bis gelappt, rot- bis kastanienbraun (Riesen-Lorchel ockerbraun); Stiel weißlich, oft gefurcht; im Längsschnitt mehrere, unregelmäßige Kammern. Schlauchpilze.","sp":"Weißlich bis creme.","oeko":"Frühjahrs-Giftlorchel unter Kiefern auf sauren Sandböden, oft an Kahlschlägen und Wegrändern im Frühjahr; Bischofsmütze im Herbst an morschem Nadelholz.","speise":"Keine Speisepilze.","gift":"Frühjahrs-Giftlorchel: Gyromitrin (wird zu Monomethylhydrazin umgewandelt) – Gyromitra-Syndrom mit Erbrechen, Leber- und Nervenschäden, tödlich; zusätzlich Verdacht auf Krebserregung. Auch Kochdämpfe sind gefährlich. Bischofsmütze und Riesen-Lorchel hat die DGfM im Mai 2026 von der Giftpilzliste gestrichen, weil kein Gyromitrin nachweisbar war – gegessen werden Lorcheln trotzdem nicht.","abgr":"Morcheln: Hut mit Waben/Gruben, im Längsschnitt ein einziger Hohlraum. Verpeln: Hut nur am Scheitel angewachsen. Lorcheln (Helvella): sattelförmig, im Herbst.","arten":"Frühjahrs-Giftlorchel (G. esculenta), Riesen-Lorchel (G. gigas), Bischofsmütze (G. infula), Scheiben-Lorchel (G. ancilis)","tipp":"Längsschnitt: Morchel = ein Hohlraum, Giftlorchel = viele Kammern.","id":"gyromitra","incl":[],"fam":"Discinaceae"},{"name":"Helvella","de":"Lorcheln","dgfm":true,"merke":"Sattel- bis mitraförmiger, gelappter Hut auf oft tief längsgerippt-grubigem Stiel – oder becherförmig; meist im Herbst.","mk":"Hut sattelförmig, zwei- bis mehrlappig oder schüsselförmig (Langfüßer), weiß, grau bis schwarz; Stiel glatt oder mit tiefen Längsrippen und Gruben; Fleisch wachsartig-brüchig. Schlauchpilze.","sp":"Weiß.","oeko":"Am Boden in Laub- und Nadelwäldern, an Wegrändern; überwiegend Sommer und Herbst.","speise":"Keine Speisepilze: roh giftig, Inhaltsstoffe ungenügend untersucht.","abgr":"Giftlorcheln (Gyromitra): hirnartig, braun, im Frühjahr. Morcheln: wabig, Frühjahr.","arten":"Herbst-Lorchel (H. crispa), Gruben-Lorchel (H. lacunosa), Grauer Langfüßer (H. macropus)","tipp":"Herbst-Lorchel: cremeweißer Sattel auf tief gefurchtem Stiel.","id":"helvella","incl":[],"fam":"Helvellaceae"},{"name":"Hohenbuehelia","de":"Muschelinge","dgfm":true,"fam":"Pleurotaceae","merke":"Kleine, seitlich angewachsene, muschel- bis spatelförmige Seitlinge mit gelatinöser Schicht in der Huthaut; weißes Sporenpulver.","mk":"Fruchtkörper ungestielt oder kurz gestielt, grau bis graubraun, oft fein filzig; unter der Huthaut eine gallertige Schicht (beim Durchschneiden sichtbar); Lamellen weißlich bis creme, zur Ansatzstelle laufend. Mikroskopisch mit dickwandigen, spindeligen Zystiden.","sp":"Weiß.","oeko":"Saprobionten an Holz, einige am Boden; fangen mit klebrigen Hyphen Fadenwürmer (Nematoden).","speise":"Keine Speisepilze.","abgr":"Austern-Seitling: größer, ohne Gallertschicht. Stummelfüßchen (Crepidotus): Sporenpulver braun. Zwergseitlinge (Resupinatus): winzig, grau, dünn.","arten":"z. B. Hohenbuehelia petaloides (am Boden), H. atrocoerulea (an Laubholz)","tipp":"Seitling mit gallertiger Hutschicht = Muscheling.","id":"hohenbuehelia","incl":[]},{"name":"Hydnum","de":"Stoppelpilze","dgfm":true,"merke":"Fleischige Hutpilze mit weichen, leicht abbrechenden Stacheln auf der Unterseite und brüchigem, weißem Fleisch.","mk":"Hut semmelgelb, ocker bis orangebraun, oft unregelmäßig; Unterseite mit dicht stehenden, weichen Stacheln, die leicht abbrechen, oft etwas am Stiel herablaufend; Stiel kurz, weißlich; Fleisch weiß, brüchig, alt bitter.","sp":"Weiß bis creme.","oeko":"Mykorrhizapilze in Laub- und Nadelwäldern.","speise":"Semmel-Stoppelpilz (H. repandum) und Rotgelber Stoppelpilz (H. rufescens) essbar (DGfM-Positivliste); ältere Exemplare bitter.","abgr":"Habichtspilz (Sarcodon): Hut grob braun beschuppt, Stacheln braun. Korkstachelinge (Hydnellum): zäh-korkig. Semmelporling: Poren statt Stacheln.","arten":"Semmel-Stoppelpilz (H. repandum)","tipp":"Einziger häufiger „Stachelpilz“ mit brüchigem, weißem Fleisch – ungiftig und gut kenntlich.","id":"hydnum","incl":[],"fam":"Hydnaceae"},{"name":"Hypholoma","de":"Schwefelköpfe","dgfm":true,"merke":"Meist büschelig an Holz; gelbe, ziegelrote oder braune Hüte, faserige Ringzone und violett- bis purpurbraunes Sporenpulver.","mk":"Hut glatt, schwefelgelb, ziegelrot oder ockerbraun; Lamellen angewachsen, jung gelb, grünlich oder grau, dann violettbraun; Stiel faserig, mit vergänglicher, durch Sporen dunkel gefärbter Cortina- bzw. Ringzone.","sp":"Violett- bis purpurbraun.","oeko":"Saprobionten an Stümpfen und Holz von Laub- und Nadelbäumen; einige Arten in Mooren und auf Torfmoos.","speise":"Rauchblättriger Schwefelkopf (H. capnoides, an Nadelholz, Lamellen grau) essbar (DGfM-Positivliste).","gift":"Grünblättriger Schwefelkopf (H. fasciculare): bitter, Magen-Darm-Syndrom (DGfM-Liste der Giftpilze). Ziegelroter Schwefelkopf: bitter, kein Speisepilz.","abgr":"Stockschwämmchen und Gift-Häubling: Sporenpulver rostbraun. Hallimasch: Sporenpulver weiß, Hut mit Schüppchen. Träuschlinge: meist mit deutlichem Ring, nicht büschelig an Holz.","arten":"Grünblättriger Schwefelkopf (H. fasciculare), Rauchblättriger Schwefelkopf (H. capnoides), Ziegelroter Schwefelkopf (H. lateritium)","tipp":"Lamellenfarbe junger Exemplare (grünlich, grau oder gelb) und Bitterkeit unterscheiden die Arten.","id":"hypholoma","incl":[],"fam":"Strophariaceae"},{"name":"Inonotus","de":"Schillerporlinge","dgfm":true,"merke":"Einjährige, rost- bis dunkelbraune, filzige Porlinge mit seidig schillernden Poren und braunem Fleisch, das sich mit Kalilauge schwärzt.","mk":"Konsolen weich-saftig bis faserig, Oberseite filzig-striegelig, rost- bis schwarzbraun; Poren braun, bei schrägem Lichteinfall seidig glänzend („schillernd“); Fleisch rost- bis gelbbraun, faserig; Kalilauge färbt das Fleisch schwarz (typisch für die Familie der Borstenscheiblingsverwandten).","sp":"Gelb- bis rostbraun.","oeko":"Parasiten an lebenden Laubbäumen (Erle, Esche, Apfel, Birke, Eiche); Weißfäule. Der Schiefe Schillerporling bildet an Birke schwarze, rissige Knollen (Chaga).","speise":"Keine Speisepilze.","abgr":"Feuerschwämme (Phellinus): mehrjährig, steinhart. Schwefelporling: leuchtend gelb, Fleisch weiß. Lackporlinge: lackige Kruste.","arten":"Zottiger Schillerporling (I. hispidus), Erlen-Schillerporling (I. radiatus), Schiefer Schillerporling (I. obliquus), Getropfter Schillerporling (I. dryadeus)","tipp":"Braune Poren mit Seidenglanz + braunes Fleisch + KOH schwarz.","id":"inonotus","incl":[],"fam":"Hymenochaetaceae"},{"name":"Laccaria","de":"Lacktrichterlinge","dgfm":true,"merke":"Dicke, entfernt stehende, fleischrosa oder violette Lamellen, oft weiß bepudert; zäher, faseriger Stiel; weißes Sporenpulver.","mk":"Hut hygrophan, oft fein schuppig-rau, fleischrot bis violett; Lamellen dick, wachsartig wirkend, weit entfernt, gleichfarbig, durch die Sporen weißlich bereift; Stiel längsfaserig, zäh.","sp":"Weiß.","oeko":"Mykorrhizapilze bei Laub- und Nadelbäumen; sehr häufig.","speise":"Violetter (L. amethystina) und Rötlicher Lacktrichterling (L. laccata) essbar (DGfM-Positivliste), nur die Hüte; der Violette reichert Arsen an.","abgr":"Rettich-Helmling (Mycena pura): Rettichgeruch, dünnere Lamellen, giftig. Violetter Rötelritterling: fleischig, Sporenpulver rosa. Schleierlinge: Cortina, rostbraune Sporen.","arten":"Violetter Lacktrichterling (L. amethystina), Rötlicher Lacktrichterling (L. laccata)","tipp":"Dicke, weit stehende Lamellen in Hutfarbe – „Bläuling“ bzw. „Lackpilz“.","id":"laccaria","incl":[],"fam":"Hydnangiaceae"},{"name":"Lactarius","de":"Milchlinge, Reizker","dgfm":true,"incl":["Lactifluus"],"merke":"Brüchiges, kreidiges Fleisch, das bei Verletzung Milch absondert.","mk":"Fleisch körnig-brüchig (Kugelzellen), Stiel bricht glatt wie Kreide; bei Verletzung tritt Milchsaft aus – weiß, wässrig, orange bis karottenrot oder an der Luft gelb bzw. violett verfärbend; Geschmack der Milch mild, bitter oder scharf. Hut oft trichterig, teils konzentrisch gezont; Lamellen angewachsen bis herablaufend.","sp":"Weiß bis creme oder ocker.","oeko":"Mykorrhizapilze, oft an bestimmte Baumarten gebunden (Birke, Fichte, Kiefer, Buche, Eiche).","speise":"Echte Reizker mit oranger Milch (Edel-, Fichten-, Lachs-Reizker), Brätling (§) und Pfeffer-Milchling (gut durchgaren) sind essbar (DGfM-Positivliste). Birken-Reizker, Rotbrauner Milchling und Pech-Milchling nur nach besonderer Zubereitung (uneinheitlich).","gift":"Bruch-Reizker (L. helvus): Magen-Darm-Syndrom. Mordschwamm (L. turpis): Magen-Darm-Beschwerden, Verdacht auf Krebserregung. Scharfe Arten gelten roh als magen-darm-giftig.","abgr":"Täublinge: gleiches brüchiges Fleisch, aber keine Milch. Kremplinge: Lamellen ablösbar, keine Milch.","arten":"Edel-Reizker (L. deliciosus), Fichten-Reizker (L. deterrimus), Birken-Reizker (L. torminosus), Mordschwamm (L. turpis), Brätling (Lactifluus volemus), Pfeffer-Milchling (Lactifluus piperatus)","tipp":"Drei Merkmale: Milchsaft, brüchiges Fleisch, Stiel bricht glatt; zur Bestimmung Milchfarbe, Verfärbung und Geschmack prüfen.","id":"lactarius","fam":"Russulaceae"},{"name":"Lepiota","de":"Schirmlinge","dgfm":true,"merke":"Kleine bis mittelgroße Schirmlinge mit freien Lamellen, weißem Sporenpulver, Schüppchen auf hellem Grund und Ring bzw. Ringzone – viele Arten giftig, einige tödlich.","mk":"Hut mit konzentrisch angeordneten, braunen, rötlichen oder rosa Schüppchen auf weißlichem Grund, Mitte meist geschlossen dunkler; Lamellen frei, weiß bis creme; Stiel mit häutigem Ring oder flockiger Ringzone, darunter oft beflockt; keine Volva.","sp":"Weiß.","oeko":"Saprobionten in Laub- und Nadelwäldern, Parks und Gärten, oft auf nährstoffreichen Böden.","speise":"Keine Speisepilze.","gift":"Mehrere kleine Arten enthalten Amatoxine (z. B. Fleischbräunlicher Schirmling L. brunneoincarnata, L. subincarnata, L. elaiophylla) – Phalloides-Syndrom, tödlich. Stink-Schirmling (L. cristata): giftig. Spitzschuppiger Stachelschirmling (Echinoderma asperum): mit Alkohol giftig.","abgr":"Riesenschirmlinge: viel größer, verschiebbarer Ring, Stiel genattert. Champignons: braunes Sporenpulver. Körnchenschirmlinge: angewachsene Lamellen.","arten":"Fleischbräunlicher Schirmling (L. brunneoincarnata), Stink-Schirmling (L. cristata), Wollstiel-Schirmling (L. clypeolaria)","tipp":"Faustregel für die Beratung: Schirmlinge mit weniger als 10 cm Hutdurchmesser nie zum Essen freigeben.","id":"lepiota","incl":[],"fam":"Agaricaceae"},{"name":"Lepista","de":"Rötelritterlinge","dgfm":true,"merke":"Fleischige Ritterlinge mit blass rosa Sporenpulver und Lamellen, die sich leicht vom Hutfleisch ablösen lassen.","mk":"Hut glatt, fleischig, violett, grau, lederbraun oder fuchsig; Lamellen ausgebuchtet bis herablaufend, leicht vom Hutfleisch abtrennbar; Geruch oft aromatisch-parfümiert; Sporen fein warzig (mikroskopisch).","sp":"Blass rosa bis cremerosa.","oeko":"Saprobionten in Laub- und Nadelstreu, auf Wiesen, in Hecken und auf Kompost; oft in Hexenringen.","speise":"Violetter, Lilastiel-, Schmutziger und Graubrauner Rötelritterling essbar (DGfM-Positivliste), roh giftig. Fuchsiger Rötelritterling uneinheitlich (ungeklärte muscarinartige Symptome).","abgr":"Schleierlinge (Cortinarius): Cortina, rostbraune Sporen. Parfümierter Trichterling (Paralepistopsis amoenolens): ähnlich wie der Fuchsige Rötelritterling, Orangenblütengeruch – Acromelalgie. Trichterlinge: Sporenpulver weiß.","arten":"Violetter Rötelritterling (L. nuda), Lilastiel-Rötelritterling (L. personata), Fuchsiger Rötelritterling (L. flaccida)","tipp":"Drei Gattungsmerkmale: blass rosa Sporenpulver, ablösbare Lamellen, warzige Sporen; violette Arten nicht mit violetten Schleierlingen verwechseln (Cortina!).","id":"lepista","incl":[],"fam":"Tricholomataceae"},{"name":"Lichenes","de":"Flechten","dgfm":true,"merke":"Lebensgemeinschaften (Symbiosen) aus einem Pilz und einem Photosynthese-Partner (Grünalge oder Cyanobakterium).","mk":"Keine Gattung, sondern eine Lebensform: Der Pilzpartner (meist ein Schlauchpilz) bildet den Flechtenkörper (Thallus), in dem Algen oder Cyanobakterien Photosynthese betreiben. Wuchsformen: Krusten-, Blatt- (Laub-) und Strauchflechten. Vermehrung über Pilzsporen oder über Brutkörper (Soredien, Isidien), die beide Partner enthalten.","oeko":"Auf Rinde, Gestein, Holz und Boden, auch an extremen Standorten; viele Arten reagieren empfindlich auf Luftverschmutzung und werden als Zeiger für Luftgüte genutzt.","speise":"Keine Speisepilze; Isländisches Moos (Cetraria islandica) dient als Heilmittel.","abgr":"Moose: grüne Pflanzen mit Blättchen. Schleimpilze: keine Symbiose, kriechendes Plasmodium.","arten":"Gelbe Wandflechte (Xanthoria parietina), Pflaumenflechte (Evernia prunastri), Isländisches Moos (Cetraria islandica), Rentierflechten (Cladonia), Bartflechten (Usnea)","tipp":"Flechten gehören zum Reich der Pilze. Nach der BArtSchV besonders geschützt sind u. a. die Gattungen Cetraria (z. B. Isländisches Moos), Lobaria (Lungenflechten), Parmelia s. l. und die Rentierflechten (Cladonia Untergattung Cladina).","id":"lichenes","incl":[]},{"name":"Lycoperdon","de":"Stäublinge","dgfm":true,"incl":["Apioperdon","Vascellum"],"merke":"Kugel- bis birnförmige Bauchpilze mit stacheliger oder körniger Außenhülle, jung reinweißem, festem Inneren und reif olivbraun stäubender Sporenmasse, die durch ein Scheitelloch austritt.","mk":"Außenhülle (Exoperidie) mit abwischbaren Stacheln, Warzen oder Körnchen; Innenhülle papierartig, öffnet sich mit einer Mündung am Scheitel; Gleba jung weiß und fest, reif olivbraun und pulverig; meist mit sterilem, zelligem Stielteil (Subgleba).","sp":"Olivbraun.","oeko":"Saprobionten in Wäldern, auf Wiesen und Weiden; der Birnen-Stäubling auf morschem Holz.","speise":"Jung essbar, solange das Innere reinweiß und fest ist: Flaschen-Stäubling und Hasen-Stäubling (DGfM-Positivliste); ebenso der Riesenbovist.","abgr":"Kartoffelboviste (Scleroderma): dicke, derbe Hülle, Inneres früh schwarzviolett – giftig. Junge Knollenblätterpilze und Hexeneier: im Längsschnitt Lamellen oder Gallerte – immer längs durchschneiden! Boviste (Bovista): ohne sterilen Stielteil.","arten":"Flaschen-Stäubling (L. perlatum), Hasen-Stäubling (L. utriforme), Birnen-Stäubling (Apioperdon pyriforme), Wiesen-Staubbecher (Vascellum pratense)","tipp":"Drei Merkmale: Gleba im Inneren (Bauchpilz), jung weiß und fest, reif olivbraun stäubend; Außenhülle stachelig bis körnig; Öffnung am Scheitel. Jeden Stäubling zur Kontrolle längs halbieren!","id":"lycoperdon","fam":"Lycoperdaceae"},{"name":"Macrolepiota","de":"Riesenschirmlinge","dgfm":true,"incl":["Chlorophyllum"],"merke":"Große Schirmlinge mit grob geschupptem Hut, freien Lamellen, verschiebbarem (doppeltem) Ring und weißem Sporenpulver.","mk":"Hut groß, mit groben, abstehenden Schuppen und glatter, dunkler Mitte; Lamellen frei, weiß, durch einen Ring (Kollar) vom Stiel abgesetzt; Ring dick, doppelt, am Stiel verschiebbar; Stiel beim Parasol genattert, bei den Safranschirmlingen (Chlorophyllum) glatt und das Fleisch safranrot verfärbend; Basis knollig.","sp":"Weiß bis creme (Gift-Riesenschirmling C. molybdites: grünlich).","oeko":"Saprobionten an Waldrändern, auf Lichtungen, Wiesen, in Gärten und auf Kompost.","speise":"Parasol (M. procera), Zitzen-Riesenschirmling und Acker-Schirmling essbar (DGfM-Positivliste); Safran-Schirmling (C. olivieri) essbar mit individueller Unverträglichkeit.","gift":"Gartenschirmling (Chlorophyllum brunneum) und Gift-Riesenschirmling (C. molybdites): Magen-Darm-Syndrom.","abgr":"Pantherpilz und Knollenblätterpilze: Volva bzw. Knolle mit Scheide, Ring nicht verschiebbar. Kleine Schirmlinge (Lepiota): klein, teils tödlich giftig.","arten":"Parasol (M. procera), Safran-Schirmling (Chlorophyllum olivieri), Gartenschirmling (Chlorophyllum brunneum)","tipp":"Verschiebbarer Ring und genatterter Stiel = Parasol; Lamellen an einem Kollar.","id":"macrolepiota","fam":"Agaricaceae"},{"name":"Marasmius","de":"Schwindlinge","dgfm":true,"incl":["Mycetinis","Marasmiellus"],"merke":"Zähe, lederartige Pilzchen, die bei Trockenheit schrumpfen und bei Nässe wieder aufleben; hornartig-zäher Stiel; weißes Sporenpulver.","mk":"Hut dünn, oft gefurcht oder gerieft; Lamellen meist entfernt, manchmal an einem Halsband (Kollar) um die Stielspitze angewachsen (Halsband-Schwindling); Stiel dünn, zäh, oft dunkel und glänzend wie Rosshaar; Fruchtkörper faulen kaum, sondern trocknen ein.","sp":"Weiß.","oeko":"Saprobionten auf Laub, Nadeln, Grasresten, Holz und in Wiesen (Nelken-Schwindling in Hexenringen).","speise":"Nelken-Schwindling (M. oreades) und Knoblauch-Schwindlinge (Mycetinis) essbar (DGfM-Positivliste); Hüte als Würzpilze.","abgr":"Feld-Trichterling (Clitocybe rivulosa): in denselben Wiesen, weiß bereift, Lamellen dicht und herablaufend – Muscarin, lebensgefährlich! Rüblinge: weniger zäh, leben nicht wieder auf.","arten":"Nelken-Schwindling (M. oreades), Halsband-Schwindling (M. rotula), Mousseron (Mycetinis scorodonius)","tipp":"Halsband-Schwindling: Lamellen an einem Kollar – Gattungsbeispiel für „Kollar“.","id":"marasmius","fam":"Marasmiaceae"},{"name":"Melanoleuca","de":"Weichritterlinge","dgfm":true,"merke":"Flacher, glatter Hut mit kleinem Buckel, dichte weiße bis creme Lamellen und ein schlanker, steifer, längsfaseriger Stiel.","mk":"Hut flach ausgebreitet mit kleinem Buckel, glatt, oft dunkel graubraun, hygrophan; Lamellen ausgebuchtet, dicht, weiß bis creme; Stiel schlank, steif, längsfaserig gestreift, Basis oft verdickt; Fleisch im Hut weich, im Stiel faserig. Mikroskopisch amyloide, warzige Sporen und typische „Brennhaar“-Zystiden.","sp":"Weiß bis creme.","oeko":"Saprobionten auf Wiesen, in Wäldern, Gärten und an Wegrändern; einige Arten bereits im Frühjahr.","speise":"Frühlings-Weichritterling (M. cognata) essbar (DGfM-Positivliste); die Arten sind schwer zu unterscheiden.","abgr":"Ritterlinge (Tricholoma): fleischiger, Hut meist nicht flach gebuckelt. Rötlinge: rosa Sporenpulver. Mairitterling: dick, Mehlgeruch.","arten":"Frühlings-Weichritterling (M. cognata)","tipp":"Flacher Hut mit Buckel auf „Gewehrstiel“.","id":"melanoleuca","incl":[],"fam":"Pluteaceae"},{"name":"Morchella","de":"Morcheln","dgfm":true,"merke":"Wabenartig gegrubter Hut, mit dem Stiel verwachsen; Hut und Stiel bilden einen einzigen durchgehenden Hohlraum; im Frühjahr.","mk":"Hut eiförmig, rundlich oder spitzkegelig, mit Gruben zwischen Längs- und Querrippen (Waben); bei der Halbfreien Morchel nur zur Hälfte mit dem Stiel verbunden; Stiel weißlich, kleiig; Fleisch wachsartig-brüchig. Schlauchpilze.","sp":"Creme- bis ockergelblich.","oeko":"Im Frühjahr unter Eschen und Ulmen, in Auwäldern, Gärten, auf Rindenmulch, Brandstellen und unter Nadelbäumen; meist auf Kalk.","speise":"Speisepilze, aber roh giftig: mindestens 20 Minuten erhitzen, höchstens etwa 100 g pro Mahlzeit (DGfM: uneinheitlich beurteilt). Geschützt (§): nur geringe Mengen für den Eigenbedarf.","gift":"Roh Magen-Darm-Beschwerden; nach größeren Mengen neurologisches Morchella-Syndrom.","abgr":"Frühjahrs-Giftlorchel: hirnartig, gekammert – tödlich giftig. Verpeln: Hut nur am Scheitel angewachsen. Stinkmorchel: Hexenei, Volva, stinkender Schleim.","arten":"Speisemorchel (M. esculenta), Spitzmorchel (M. conica), Halbfreie Morchel (M. semilibera)","tipp":"Drei Merkmale: wabenartige Gruben; ein einziger Hohlraum (Längsschnitt); Hut mit dem Stiel verwachsen.","id":"morchella","incl":[],"fam":"Morchellaceae"},{"name":"Mycena","de":"Helmlinge","dgfm":true,"incl":["Hemimycena"],"merke":"Kleine, zerbrechliche Pilze mit glockig-kegeligem, oft gerieftem Hut auf dünnem, hohlem, brüchigem Stiel; weißes Sporenpulver.","mk":"Hut glocken- bis kegelförmig („Helm“), meist durchscheinend gerieft, oft hygrophan; Lamellen angewachsen, teils mit andersfarbiger Schneide; Stiel dünn, hohl, brüchig bis knorpelig, oft mit striegeliger Basis. Manche Arten mit Milch oder Saft (Bluthelmlinge), andere mit Rettich-, Chlor- oder Nitratgeruch. Sporen meist amyloid (mikroskopisch).","sp":"Weiß.","oeko":"Saprobionten in Laub- und Nadelstreu, an Holz, Zapfen und Pflanzenresten.","speise":"Keine Speisepilze.","gift":"Rettich-Helmling (M. pura) und Rosa Rettichhelmling (M. rosea): Muscarin-Syndrom.","abgr":"Rüblinge: Stiel zäh, nicht brüchig. Häublinge und Samthäubchen: braunes Sporenpulver. Nabelinge: herablaufende Lamellen, genabelter Hut.","arten":"Rettich-Helmling (M. pura), Großer Bluthelmling (M. haematopus), Rosablättriger Helmling (M. galericulata), Weißmilchender Helmling (M. galopus)","tipp":"Drei Merkmale: glockiger, geriefter Hut; dünner, brüchiger Hohlstiel; weißes Sporenpulver; dazu Geruch und Milch prüfen.","id":"mycena","fam":"Mycenaceae"},{"name":"Myxomycota","de":"Schleimpilze","dgfm":true,"incl":["Fuligo","Lycogala"],"merke":"Keine echten Pilze: einzellige, vielkernige Organismen, die als Schleim (Plasmodium) über Holz und Streu kriechen und dann staubende Fruchtkörper bilden.","mk":"Das Plasmodium ist eine bewegliche, oft leuchtend gelbe, weiße oder rote Schleimmasse ohne Zellwände, die Bakterien und Pilzsporen frisst. Bei Trockenheit oder Nahrungsmangel bildet es Fruchtkörper (Sporangien oder kissenförmige Aethalien), deren Inneres zu einem Sporenpulver zerfällt.","sp":"Je nach Art schwarz, braun, rosa oder gelb.","oeko":"Auf morschem Holz, Rinde, Laub, Moos und Rindenmulch, vor allem bei feuchtem Wetter.","speise":"Keine Speisepilze.","abgr":"Stäublinge und andere Bauchpilze: mit Myzel, kein kriechendes Plasmodium. Gallertpilze (Tremella): zähgallertig, nicht kriechend.","arten":"Gelbe Lohblüte (Fuligo septica), Blutmilchpilz (Lycogala epidendrum)","tipp":"Schleimpilze werden traditionell von Mykologen bearbeitet, gehören aber stammesgeschichtlich zu den Amöben (Amoebozoa).","id":"myxomycota"},{"name":"Panaeolus","de":"Düngerlinge","dgfm":true,"merke":"Glockige Hüte auf langem, brüchigem Stiel, gescheckte (marmorierte) Lamellen mit weißer Schneide und schwarzes Sporenpulver; oft auf Dung.","mk":"Hut glockig bis halbkugelig, öffnet sich kaum, grau, braun oder weißlich, teils mit Velumzähnchen am Rand oder mit Ring (Ring-Düngerling); Lamellen angewachsen, durch ungleichmäßig reifende Sporen gescheckt, Schneide weiß; Stiel lang, dünn, brüchig; Lamellen zerfließen nicht.","sp":"Schwarz (Heu-Düngerling: dunkel purpurbraun).","oeko":"Saprobionten auf Dung, gedüngten Weiden und Wiesen; der Heu-Düngerling in Rasen.","speise":"Keine Speisepilze.","gift":"Die DGfM führt die Gattung unter den psilocybinhaltigen Pilzen (sicher z. B. Panaeolus cyanescens und P. cinctulus; beim Glocken-Düngerling widersprüchlich): Psilocybin-Syndrom.","abgr":"Tintlinge: Lamellen zerfließen. Mürblinge: Lamellen nicht gescheckt, Sporenpulver dunkelbraun. Kahlköpfe: Sporenpulver purpurbraun, Lamellen nicht gescheckt.","arten":"Glocken-Düngerling (P. papilionaceus), Ring-Düngerling (P. semiovatus), Heu-Düngerling (P. foenisecii)","tipp":"Gescheckte Lamellen + schwarzes Sporenpulver = Düngerling.","id":"panaeolus","incl":[],"fam":"Galeropsidaceae"},{"name":"Peziza","de":"Becherlinge","dgfm":true,"merke":"Ungestielte, schüssel- bis becherförmige Schlauchpilze mit wachsartig-brüchigem Fleisch; Fruchtschicht auf der Innenseite.","mk":"Fruchtkörper schüssel- bis becherförmig, später oft verbogen, meist braun, ocker oder violett; Außenseite kleiig; Fleisch wachsartig-brüchig, bei einigen Arten mit Milch, die gilbt oder violett ist; Schläuche mit Deckel, an der Spitze mit Jod blau (mikroskopisch).","sp":"Weiß bis blass.","oeko":"Auf nackter Erde, Wegrändern, Brandstellen, Holz, Dung, Kompost und in Gewächshäusern.","speise":"Keine Speisepilze (roh giftig, wertlos).","abgr":"Orangebecherling (Aleuria): leuchtend orange. Kelchbecherlinge (Sarcoscypha): gestielt, scharlachrot. Morchelbecherling (Disciotis): aderige Fruchtschicht, Chlorgeruch, Frühjahr. Öhrlinge (Otidea): einseitig geschlitzt.","arten":"Kastanienbrauner Becherling (P. badia), Blasiger Becherling (P. vesiculosa), Gelbmilchender Becherling (P. succosa), Violettmilchender Becherling (P. saniosa)","tipp":"Milch (gilbend oder violett) ist bei Becherlingen ein Bestimmungsmerkmal.","id":"peziza","incl":[],"fam":"Pezizaceae"},{"name":"Phaeocollybia","de":"Wurzelschnitzlinge","dgfm":true,"merke":"Schmieriger, spitz gebuckelter, rot- bis olivbrauner Hut, rostbraune Lamellen und knorpeliger Stiel mit langer Wurzel (Pseudorhiza).","mk":"Hut kegelig bis glockig mit spitzem Buckel, schmierig, hygrophan, orange- bis rot- oder olivbraun; Lamellen fast frei, dicht, ocker- bis rostbraun; Stiel knorpelig-zäh, glatt, ohne Velumreste, in eine lange, zugespitzte Wurzel übergehend; Sporen warzig.","sp":"Rost- bis ockerbraun.","oeko":"In sauren Fichtenwäldern, oft auf nackten Moosböden; Lebensweise nicht sicher geklärt (wahrscheinlich Mykorrhiza).","speise":"Keine Speisepilze.","abgr":"Schleimrüblinge (Xerula): Lamellen und Sporenpulver weiß. Saftlinge: wachsartige Lamellen, weiße Sporen. Schleierlinge: Cortina.","arten":"Gemeiner Wurzelschnitzling (P. lugubris)","tipp":"Braunsporer mit „Pfahlwurzel“ im Fichtenwald.","id":"phaeocollybia","incl":[],"fam":"Hymenogastraceae"},{"name":"Phellinus","de":"Feuerschwämme","dgfm":true,"incl":["Fomitiporia"],"merke":"Mehrjährige, steinharte, holzige Porlinge mit rostbraunem Fleisch, feinen braunen Poren und geschichteten Röhren; Kalilauge färbt schwarz.","mk":"Fruchtkörper huf- bis konsolenförmig oder krustig; Oberseite grau bis schwarz, oft rissig-krustig; Poren sehr fein, zimt- bis rostbraun; Fleisch rost- bis gelbbraun, holzig; Röhren in Jahresschichten; mit Kalilauge schwarz (Borstenscheiblingsverwandte).","sp":"Weiß bis gelblich.","oeko":"Parasiten an lebenden Laubbäumen (Weide, Birke, Pappel, Eiche, Obstbäume), seltener Nadelbäume; Weißfäule.","speise":"Keine Speisepilze.","abgr":"Zunderschwamm: Fleisch weich-filzig, Poren hell. Lackporlinge: braunes Sporenpulver, weiße Poren. Schillerporlinge: einjährig, weich-faserig.","arten":"Falscher Zunderschwamm (P. igniarius), Eichen-Feuerschwamm (Fomitiporia robusta)","tipp":"Hart wie Holz, innen rostbraun – Feuerschwamm.","id":"phellinus","fam":"Hymenochaetaceae"},{"name":"Pholiota","de":"Schüpplinge","dgfm":true,"incl":["Kuehneromyces"],"merke":"Meist büschelig an Holz; Hut und oft Stiel mit Schuppen (trocken oder schleimig), Ringzone und rost- bis zimtbraunes Sporenpulver.","mk":"Hut trocken mit sparrigen Schuppen oder schleimig mit eingebetteten Schuppen; Lamellen angewachsen, gelblich bis olivgelb, später rostbraun; Stiel unterhalb einer Ring- oder Ringzone oft schuppig; Velum faserig bis häutig. Das Stockschwämmchen (Kuehneromyces) gehört in die nähere Verwandtschaft.","sp":"Rost- bis zimtbraun.","oeko":"Saprobionten und Schwächeparasiten an Laub- und Nadelholz; der Kohlen-Schüppling auf Brandstellen.","speise":"Stockschwämmchen essbar (DGfM-Positivliste). Sparriger, Goldfell- und Tonweißer Schüppling uneinheitlich (gelegentlich Magen-Darm-Beschwerden).","abgr":"Gift-Häubling: Hut glatt, Stiel unter dem Ring längsfaserig-silbrig – tödlich giftig. Hallimasch: Sporenpulver weiß. Schwefelköpfe: Sporenpulver violettbraun. Flämmlinge (Gymnopilus): Sporenpulver rostorange, bitter.","arten":"Sparriger Schüppling (P. squarrosa), Stockschwämmchen (Kuehneromyces mutabilis), Schleimiger Schüppling (P. adiposa), Feuer-Schüppling (P. flammans)","tipp":"Drei Merkmale: Schuppen auf Hut und Stiel; rostbraunes Sporenpulver; meist büschelig an Holz mit Ringzone.","id":"pholiota","fam":"Strophariaceae"},{"name":"Pluteus","de":"Dachpilze","dgfm":true,"merke":"Holzbewohner mit freien, jung weißen, später rosa Lamellen, rosa Sporenpulver und ohne Ring und Volva.","mk":"Hut glatt, faserig oder samtig; Lamellen frei, dicht, bauchig, erst weiß, dann fleischrosa; Stiel ohne Velum, leicht aus dem Hut zu brechen; mikroskopisch typische Zystiden (bei der Rehbraun-Gruppe mit hakenförmigen Hörnchen).","sp":"Rosa.","oeko":"Saprobionten auf totem Holz, Stümpfen, Holzresten und Sägemehl.","speise":"Rehbrauner Dachpilz essbar (DGfM-Positivliste), aber wenig schmackhaft.","gift":"Weiden-Dachpilz (P. salicinus): Psilocybin.","abgr":"Scheidlinge (Volvariella, Volvopluteus): rosa Lamellen, aber mit Volva. Rötlinge: Lamellen angewachsen, am Boden. Breitblättriger Holzrübling: Sporenpulver weiß.","arten":"Rehbrauner Dachpilz (P. cervinus), Weiden-Dachpilz (P. salicinus), Schwarzschneidiger Dachpilz (P. nigrofloccosus)","tipp":"Drei Merkmale: freie, rosa werdende Lamellen; rosa Sporenpulver; kein Velum; Holzbewohner.","id":"pluteus","incl":[],"fam":"Pluteaceae"},{"name":"Polyporales","de":"Porlinge","dgfm":true,"incl":["Antrodia","Bjerkandera","Daedalea","Daedaleopsis","Fomes","Fomitopsis","Ganoderma","Grifola","Hapalopilus","Ischnoderma","Laetiporus","Lenzites","Meripilus","Phaeolus","Physisporinus","Piptoporus","Polyporus","Postia","Pycnoporellus","Pycnoporus","Skeletocutis","Trametes"],"merke":"Ordnung der „Porlinge“: überwiegend holzbewohnende Pilze mit einer Porenschicht, die nicht als Röhrenschicht vom Fleisch abgelöst werden kann.","mk":"Keine Gattung, sondern eine große Pilzordnung. Fruchtkörper konsolen-, hut- oder krustenförmig, weich-fleischig, korkig, ledrig oder holzig, ein- oder mehrjährig; Fruchtschicht meist porig, seltener labyrinthisch oder lamellig (Blättlinge, Sägeblättlinge); Hyphensystem mono-, di- oder trimitisch (mikroskopisch). Zur Gattung Polyporus (Stielporlinge) gehören die gestielten Arten.","sp":"Meist weiß; bei den Lackporlingen braun.","oeko":"Holzzersetzer, die Weißfäule (Abbau von Lignin) oder Braunfäule (Abbau der Zellulose) verursachen; viele auch als Parasiten an lebenden Bäumen.","speise":"Jung essbar sind z. B. Schuppiger Porling, Sklerotien-Porling, Riesenporling, Klapperschwamm und Eichhase (DGfM-Positivliste); Schwefelporling uneinheitlich beurteilt.","gift":"Zimtfarbener Weichporling (Hapalopilus nidulans): Polyporsäure – Nieren- und Nervenschäden, violetter Urin.","abgr":"Röhrlinge: am Boden, weich, Röhrenschicht leicht ablösbar. Feuerschwämme und Schillerporlinge (Hymenochaetales): braunes Fleisch, mit Kalilauge schwarz. Bodenporlinge (Albatrellus): am Boden, Mykorrhiza.","arten":"Zunderschwamm (Fomes fomentarius), Schmetterlings-Tramete (Trametes versicolor), Schwefelporling (Laetiporus sulphureus), Riesenporling (Meripilus giganteus), Schuppiger Porling (Polyporus squamosus)","tipp":"Weißfäule = Holz wird hell und faserig; Braunfäule = Holz wird braun und zerfällt würfelig.","id":"polyporales"},{"name":"Psathyrella","de":"Mürblinge, Faserlinge","dgfm":true,"merke":"Zerbrechliche, dünnfleischige Pilze mit hygrophanem Hut, weißem Hohlstiel, Velumresten am Hutrand und dunkelbraunem Sporenpulver; Lamellen zerfließen nicht.","mk":"Hut dünn, hygrophan, oft mit faserigen oder behangenen Velumresten am Rand; Lamellen angewachsen, grau- bis dunkelbraun, nicht zerfließend; Stiel weiß, hohl, sehr brüchig („mürbe“).","sp":"Dunkelbraun bis purpurschwarz.","oeko":"Saprobionten an Holz, Stümpfen, in der Streu, auf Wiesen und an nährstoffreichen Stellen.","speise":"Behangener Faserling und Weißstieliges Stockschwämmchen essbar (DGfM-Positivliste), aber sehr dünnfleischig.","abgr":"Tintlinge: Lamellen zerfließen, Sporenpulver schwarz. Düngerlinge: Lamellen gescheckt. Stockschwämmchen und Gift-Häubling: Sporenpulver rostbraun.","arten":"Behangener Faserling (P. candolleana), Weißstieliges Stockschwämmchen (P. piluliformis)","tipp":"Sehr brüchiger Stiel, dunkles Sporenpulver, nicht zerfließend.","id":"psathyrella","incl":[],"fam":"Psathyrellaceae"},{"name":"Psilocybe","de":"Kahlköpfe","dgfm":true,"merke":"Kleine Pilze mit kegeligem bis glockigem, schmierigem, hygrophanem Hut, purpurbraunem Sporenpulver und zähem Stiel; viele Arten psilocybinhaltig.","mk":"Hut oft spitz kegelig mit Papille, schmierig, mit abziehbarer gelatinöser Huthaut, hygrophan; Lamellen angewachsen, graubraun bis violettschwarz; Stiel dünn, zäh-biegsam; psilocybinhaltige Arten verfärben sich an Verletzungen und an der Stielbasis oft blau (Psilocin).","sp":"Purpurbraun bis violettschwarz.","oeko":"Saprobionten in Wiesen und Weiden, an Holzresten und auf Rindenmulch.","speise":"Keine Speisepilze.","gift":"Spitzkegeliger Kahlkopf und weitere Arten: Psilocybin-Syndrom; psilocybinhaltige Pilze fallen unter das Betäubungsmittelgesetz.","abgr":"Düngerlinge: gescheckte Lamellen, Sporenpulver schwarz. Samthäubchen: rostbraune Sporen. Träuschlinge: größer, meist mit Ring.","arten":"Spitzkegeliger Kahlkopf (P. semilanceata)","tipp":"Spitzkegeliger Hut mit Papille in der Weide – Psilocybin!","id":"psilocybe","incl":[],"fam":"Hymenogastraceae"},{"name":"Ramaria","de":"Korallen","dgfm":true,"merke":"Korallenartig vielfach verzweigte, fleischige Fruchtkörper aus einem gemeinsamen Strunk; ockerfarbenes Sporenpulver; die DGfM führt Korallen als magen-darm-giftig.","mk":"Fruchtkörper strauchartig verzweigt, gelb, orange, lachsrosa, violett oder ocker; Strunk meist weiß und dick; Fleisch brüchig oder zäh, oft bitter; manche Arten verfärben sich bei Verletzung (weinrot, blutrot); Sporen warzig.","sp":"Ocker- bis gelbbraun.","oeko":"Mykorrhizapilze in Laub- und Nadelwäldern; einige Arten (z. B. Steife Koralle) als Saprobionten an Holz.","speise":"Keine Speisepilze.","gift":"Dreifarbige Koralle (R. formosa), Blasse Koralle (R. pallida) und weitere Arten: Magen-Darm-Syndrom (DGfM-Liste der Giftpilze: Ramaria spp.).","abgr":"Krause Glucke: blattartig-kraus. Wiesenkeulen und Korallenpilze der Gattungen Clavulina und Clavulinopsis: Sporenpulver weiß, kleiner. Hörnlinge (Calocera): gallertig-zäh, an Holz. Lederkorallen (Thelephora): ledrig, braun.","arten":"Dreifarbige Koralle (R. formosa), Blutrotfleckende Koralle (R. sanguinea), Steife Koralle (R. stricta)","tipp":"Korallen sind wegen der schwierigen Artbestimmung und der DGfM-Einstufung nicht zum Essen freizugeben.","id":"ramaria","incl":[],"fam":"Gomphaceae"},{"name":"Resupinatus","de":"Zwergseitlinge","dgfm":true,"fam":"Pleurotaceae","merke":"Winzige, graue, seitlich oder rückseitig angewachsene, napf- bis muschelförmige Seitlinge an Holz.","mk":"Fruchtkörper 0,2–1 cm, ungestielt, dem Holz mit der Oberseite oder seitlich anhaftend; grau bis graubraun, oft fein filzig, mit gallertiger Schicht; Lamellen strahlig, grau.","sp":"Weiß.","oeko":"Saprobionten auf morschem Laubholz und Rinde, an feuchten Stellen.","speise":"Keine Speisepilze.","abgr":"Muschelinge (Hohenbuehelia): größer. Stummelfüßchen (Crepidotus): Sporenpulver braun. Austern-Seitling: viel größer.","arten":"z. B. Resupinatus applicatus","tipp":"Winzige graue Näpfchen mit Lamellen auf morschem Holz – mit Lupe suchen.","id":"resupinatus","incl":[]},{"name":"Russula","de":"Täublinge","dgfm":true,"merke":"Kreidig-brüchiges Fleisch ohne Milch; der Stiel bricht glatt wie Kreide; Lamellen oft splitternd; kein Velum.","mk":"Hut oft lebhaft gefärbt, Huthaut je nach Art abziehbar; Lamellen angewachsen bis fast frei, oft beim Darüberstreichen splitternd (Ausnahme Frauen-Täubling); Stiel meist weiß, ohne Ring und Volva; Fleisch aus Kugelzellen, brüchig wie Kreide; Geschmack mild, scharf oder bitter.","sp":"Weiß, creme, ocker bis dunkelgelb.","oeko":"Mykorrhizapilze, oft an bestimmte Baumarten gebunden.","speise":"Viele milde Arten sind gute Speisepilze (z. B. Speise-, Frauen-, Grünfelderiger, Leder- und Apfel-Täubling; DGfM-Positivliste).","gift":"Scharfe und bittere Täublinge (z. B. Spei-Täubling, Buchen-Speitäubling, Zitronenblättriger Täubling): Magen-Darm-Syndrom.","abgr":"Milchlinge: gleiches brüchiges Fleisch, aber mit Milch. Knollenblätterpilze: Ring und Volva – grüne und weiße Täublinge immer vollständig mit Stielbasis prüfen!","arten":"Speise-Täubling (R. vesca), Frauen-Täubling (R. cyanoxantha), Grünfelderiger Täubling (R. virescens), Spei-Täubling (R. emetica)","tipp":"Drei Merkmale: brüchiges Fleisch, Stiel bricht glatt; keine Milch; kein Velum. Für die Artbestimmung wichtig: Sporenpulverfarbe, Geschmack, Baumpartner.","id":"russula","incl":[],"fam":"Russulaceae"},{"name":"Scleroderma","de":"Hartboviste, Kartoffelboviste","dgfm":true,"merke":"Knollige Bauchpilze mit derber, lederartiger Hülle und früh schwarzvioletter, weiß marmorierter Sporenmasse – giftig.","mk":"Fruchtkörper kugelig bis knollig, ohne oder mit kurzem, stielartigem Fuß und Myzelsträngen; Hülle (Peridie) dick und hart oder dünn, gelblich bis braun, oft schuppig-felderig oder warzig; Gleba sehr früh schwarzviolett, von weißen Adern durchzogen, reif olivbraun-pulverig; ohne vorgebildete Öffnung, die Hülle reißt unregelmäßig auf.","sp":"Sporenmasse schwarzviolett, reif olivbraun.","oeko":"Mykorrhizapilze bei Laub- und Nadelbäumen, oft auf sauren, sandigen Böden.","speise":"Keine Speisepilze.","gift":"Scleroderma-Syndrom (Magen-Darm-Beschwerden, Schwindel, Kreislaufkollaps).","abgr":"Stäublinge: Inneres jung reinweiß, Hülle dünn mit Stacheln. Trüffeln: unterirdisch, Schlauchpilze. Wurzeltrüffeln: Hülle dünn, Inneres olivbraun gekammert.","arten":"Hartschaliger Kartoffelbovist (S. citrinum), Dünnschaliger Kartoffelbovist (S. verrucosum)","tipp":"Früher zum Strecken von Trüffeln missbraucht. Im Schnitt früh schwarzviolett mit weißen Adern; Trüffeln sind innen hell- bis dunkelbraun marmoriert und duften stark.","id":"scleroderma","incl":[],"fam":"Sclerodermataceae"},{"name":"Suillus","de":"Schmierröhrlinge","dgfm":true,"merke":"Röhrlinge mit schleimig-schmieriger, oft abziehbarer Huthaut, häufig mit Ring oder Drüsenpunkten am Stiel – streng an Nadelbäume gebunden.","mk":"Hut schleimig bis schmierig, selten filzig (Sand-Röhrling); Poren gelb, olivgelb bis grauweiß, oft eckig und weit, bei einigen jung tropfend; Stiel mit häutigem, schleimigem Ring oder mit drüsigen Körnchen; Fleisch weich.","sp":"Olivbraun.","oeko":"Mykorrhizapilze, an Kiefer, Lärche, Zirbe und Douglasie gebunden.","speise":"Viele essbar (DGfM-Positivliste: z. B. Butterpilz, Körnchen-, Gold-, Kuh-, Sand- und Grauer Lärchen-Röhrling); die schleimige Huthaut abziehen.","abgr":"Dickröhrlinge: Hut trocken, Stiel dick mit Netz. Filzröhrlinge: Hut trocken-samtig. Gelbfüße (Chroogomphus) und Schmierlinge (Gomphidius): Lamellen statt Röhren.","arten":"Beringter Butterpilz (S. luteus), Körnchen-Röhrling (S. granulatus), Gold-Röhrling (S. grevillei), Kuh-Röhrling (S. bovinus)","tipp":"Baumpartner bestimmen: Lärche (Gold-, Grauer Lärchen-Röhrling) oder Kiefer (Butterpilz, Körnchen-, Kuh-, Sand-Röhrling).","id":"suillus","incl":[],"fam":"Suillaceae"},{"name":"Tricholoma","de":"Ritterlinge","dgfm":true,"merke":"Fleischige Lamellenpilze mit ausgebuchtet angewachsenen Lamellen und weißem Sporenpulver; Mykorrhizapilze mit oft markantem Geruch.","mk":"Hut trocken faserig, schuppig oder schmierig; Lamellen ausgebuchtet angewachsen („mit Zahn“); Stiel kräftig, meist ohne Velum (einige mit Ringzone oder Gürteln); Geruch oft typisch (Mehl, Seife, Leuchtgas, Erde).","sp":"Weiß.","oeko":"Mykorrhizapilze bei Laub- und Nadelbäumen.","speise":"Essbar z. B. Erd-Ritterling, Gilbender Erd-Ritterling, Seidiger Ritterling, Grauer Ritterling (DGfM-Positivliste).","gift":"Tiger-Ritterling: schweres Magen-Darm-Syndrom. Schwefel-Ritterling: Magen-Darm-Syndrom. Grünling (T. equestre): Rhabdomyolyse (Equestre-Syndrom), Todesfälle; zudem §§ geschützt.","abgr":"Rötelritterlinge: Sporenpulver blass rosa, Lamellen ablösbar. Rötlinge: Sporenpulver rosa. Schnecklinge: dicke, wachsartige Lamellen. Weichritterlinge: flacher Hut mit Buckel, steifer Stiel. Risspilze: braunes Sporenpulver.","arten":"Erd-Ritterling (T. terreum), Grünling (T. equestre), Tiger-Ritterling (T. pardalotum), Schwefel-Ritterling (T. sulphureum)","tipp":"Drei Merkmale: ausgebuchtet angewachsene Lamellen; weißes Sporenpulver; fleischiger Fruchtkörper meist ohne Velum.","id":"tricholoma","incl":[],"fam":"Tricholomataceae"},{"name":"Tuber","de":"Echte Trüffeln","dgfm":true,"merke":"Unterirdische, knollige Schlauchpilze mit warziger oder glatter Hülle und fester, hell-dunkel marmorierter Innenmasse – alle heimischen Arten §§ geschützt.","mk":"Fruchtkörper unterirdisch (hypogäisch), rundlich-knollig; Hülle schwarz mit pyramidenförmigen Warzen (Sommer-, Wintertrüffel) oder glatt und hell (Weiße Trüffeln); Inneres fest, von hellen und dunklen Adern marmoriert; Sporen in Schläuchen, oft ornamentiert; intensiver Geruch, der Tiere anlockt.","sp":"Sporen braun (kein Sporenpulver).","oeko":"Mykorrhizapilze bei Eiche, Buche, Hasel, Linde und Kiefer, meist auf kalkhaltigen, lockeren Böden; werden mit Hunden oder Schweinen gesucht.","speise":"Sommer- und Burgunder-Trüffel, Winter-Trüffel essbar (DGfM-Positivliste) – aber besonders geschützt (§§).","abgr":"Hirschtrüffeln (Elaphomyces): Inneres purpurschwarz pulverig. Kartoffelboviste: oberirdisch, Inneres schwarzviolett. Wurzeltrüffeln (Rhizopogon): Basidiomyceten, Gleba gekammert.","arten":"Sommer-Trüffel (T. aestivum), Winter-Trüffel (T. brumale)","tipp":"Drei Merkmale: unterirdisch; marmoriertes, festes Inneres; Schlauchpilz mit kräftigem Duft.","id":"tuber","incl":[],"fam":"Tuberaceae"},{"name":"Xerocomus","de":"Filzröhrlinge","dgfm":true,"incl":["Xerocomellus","Hortiboletus","Imleria","Pseudoboletus"],"merke":"Kleine bis mittelgroße Röhrlinge mit trockenem, samtig-filzigem Hut, schlankem Stiel ohne Netz und weiten, gelben bis olivgelben Poren.","mk":"Hut trocken, samtig bis wildlederartig, im Alter oft rissig; Poren weit, eckig, gelb bis olivgelb, oft blauend; Stiel schlank, glatt, faserig oder gerippt, ohne echtes Netz; Fleisch weich, oft blauend. Die Marone (Imleria badia) wurde früher als Xerocomus badius geführt.","sp":"Olivbraun.","oeko":"Mykorrhizapilze bei Laub- und Nadelbäumen; der Parasitische Röhrling wächst auf Kartoffelbovisten.","speise":"Ziegenlippe, Rotfuß-Röhrling, Marone (DGfM-Positivliste) essbar; ältere Exemplare oft verschimmelt (Goldschimmel) – nicht verwenden.","abgr":"Dickröhrlinge: dicker, bauchiger Stiel mit Netz. Schmierröhrlinge: schleimiger Hut. Goldblatt (Phylloporus): Lamellen statt Röhren. Pfeffer-Röhrling: kupferrote Poren, scharf.","arten":"Ziegenlippe (X. subtomentosus), Rotfuß-Röhrling (Xerocomellus chrysenteron), Maronen-Röhrling (Imleria badia), Parasitischer Röhrling (Pseudoboletus parasiticus)","tipp":"Samthut + weite gelbe Poren + schlanker Stiel ohne Netz.","id":"xerocomus","fam":"Boletaceae"}];
